<script setup lang="ts">
import PlanIpAllowance from "./PlanIpAllowance.vue";
import { computed, onUnmounted, ref, watch } from "vue";
import Modal from "@papilio/ui/Modal.vue";
import NumField from "@papilio/ui/NumField.vue";
import { ApiError, item, request, query, type AccountPreferences, type CheckoutCreate, type CheckoutRetirement, type CheckoutCancel, type CheckoutReconfirm, type CheckoutIntent, type CheckoutOffer, type Page, type PaymentDestination, type Plan } from "@papilio/api";
import { asciiDigits, faDate, toman } from "@papilio/ui";
import TopupEvidence from "./TopupEvidence.vue";
const props=defineProps<{open:boolean;plan:Plan|null;checkoutId:number|null;preferences:AccountPreferences|null}>();
const emit=defineEmits<{close:[];saved:[value:CheckoutIntent]}>();
const offer=ref<CheckoutOffer|null>(null),intent=ref<CheckoutIntent|null>(null);
const busy=ref(false),error=ref(""),readState=ref<"loading"|"ready"|"error">("loading");
const funding=ref<"wallet_only"|"approved_topup">("wallet_only"),amount=ref(""),autoRenew=ref(false),changeAction=ref<"require_confirmation"|"cancel">("require_confirmation");
const destinations=ref<PaymentDestination[]>([]),destination=ref<PaymentDestination|null>(null),destinationQuery=ref(""),page=ref(1),pages=ref(1),destinationState=ref<"idle"|"loading"|"ready"|"error">("idle");
const createUncertain=ref(false),actionUncertain=ref(false),retirementPending=ref(false);
const retirementMessage=ref("");
const createAttempt=ref<CheckoutCreate|null>(null),actionAttempt=ref<{action:"reconfirm";body:CheckoutReconfirm}|{action:"cancel";body:CheckoutCancel}|null>(null);
let version=0,destinationVersion=0;
const unresolved=computed(()=>Boolean(createAttempt.value&&!intent.value));
const terminal=computed(()=>intent.value&&["purchased","cancelled","expired"].includes(intent.value.state));
const labels:Record<CheckoutIntent["state"],string>={awaiting_funding:"Waiting for payment approval",ready:"Ready for purchase processing",action_required:"Review required",purchased:"Purchase recorded",cancelled:"Cancelled",expired:"Expired"};
const reasonMessage=computed(()=>{const row=intent.value;if(!row?.reason_code||row.state==="cancelled"||row.state==="expired")return null;if(row.reason_code==="checkout_offer_busy")return row.state==="action_required"?"Connection inventory was busy. Review and confirm the current offer to try again.":"Connection inventory is temporarily busy. This checkout remains queued for another check before its deadline.";if(row.reason_code==="checkout_offer_changed")return "The plan or price changed. Review the current offer before confirming.";if(row.reason_code==="wallet_insufficient")return "Your wallet needs more funds to complete this checkout before its deadline.";if(row.reason_code==="checkout_topup_rejected")return "This payment request was rejected. Review your payment and checkout before continuing.";return "This checkout needs attention. Refresh its status to review the current outcome.";});
function fail(cause:unknown):void{error.value=cause instanceof Error?cause.message:"Could not complete checkout. Your request is retained.";}
function retain(row:CheckoutIntent):void{intent.value=row;emit("saved",row);}
async function loadOffer(planId:number):Promise<CheckoutOffer>{return item<CheckoutOffer>(`/v1/customer/checkouts/offers/${planId}`);}
async function refresh():Promise<void>{const stamp=++version;busy.value=true;error.value="";readState.value="loading";try{const id=intent.value?.id??props.checkoutId;if(id!==null){const row=await item<CheckoutIntent>(`/v1/customer/checkouts/${id}`);if(stamp!==version)return;intent.value=row;if(row.state==="action_required"){const current=await loadOffer(row.plan_id);if(stamp!==version)return;offer.value=current;}}else if(props.plan){const current=await loadOffer(props.plan.id);if(stamp!==version)return;offer.value=current;}if(stamp===version)readState.value="ready";}catch(cause){if(stamp===version){readState.value="error";fail(cause);}}finally{if(stamp===version)busy.value=false;}}
async function loadDestinations():Promise<void>{const stamp=++destinationVersion;destinationState.value="loading";try{const result=await request<Page<PaymentDestination>>(`/v1/customer/payment-destinations?${query({page:page.value,q:destinationQuery.value})}`);if(stamp!==destinationVersion)return;destinations.value=result.data;pages.value=result.meta.pager?.total_pages??1;destinationState.value="ready";}catch(cause){if(stamp===destinationVersion){destinationState.value="error";fail(cause);}}}
async function create():Promise<void>{if(!offer.value||retirementPending.value)return;const stamp=version;error.value="";retirementMessage.value="";try{if(!createAttempt.value){if(!Number.isSafeInteger(offer.value.default_expiry_seconds)||Number(offer.value.default_expiry_seconds)<=0)throw new Error("Checkout lifetime is unavailable. Refresh the offer before purchasing.");let rial:number|null=null;if(funding.value==="approved_topup"){if(!props.preferences)throw new Error("Payment settings are unavailable. Reload your account before requesting payment.");const normalized=asciiDigits(amount.value);if(!/^\d+(?:\.\d)?$/.test(normalized))throw new Error("Enter a top-up amount in toman with at most one decimal place.");rial=Math.round(Number(normalized)*10);if(!Number.isSafeInteger(rial)||rial<=0)throw new Error("Enter a valid top-up amount.");if(props.preferences?.checkout.destination_mode==="required"&&!destination.value)throw new Error("Select a payment destination.");}createAttempt.value={request_key:crypto.randomUUID(),plan_id:offer.value.plan_id,funding_mode:funding.value,expected_offer_sha256:offer.value.offer_sha256,expected_price_rial:offer.value.price_rial,auto_renew:autoRenew.value,expiry_seconds:Number(offer.value.default_expiry_seconds),changed_offer_action:changeAction.value,topup_amount_rial:rial,destination_id:funding.value==="approved_topup"&&props.preferences?.checkout.destination_mode!=="legacy"?destination.value?.destination_id??null:null};}busy.value=true;const row=await item<CheckoutIntent>("/v1/customer/checkouts","POST",createAttempt.value);if(stamp!==version)return;retain(row);createAttempt.value=null;createUncertain.value=false;}catch(cause){if(stamp!==version)return;if(createAttempt.value){if(cause instanceof ApiError&&cause.status>=400&&cause.status<500&&!createUncertain.value)createAttempt.value=null;else createUncertain.value=true;}fail(cause);}finally{if(stamp===version)busy.value=false;}}
async function retire():Promise<void>{
 if(!createAttempt.value||intent.value)return;
 const stamp=version,key=createAttempt.value.request_key;
 retirementPending.value=true;busy.value=true;error.value="";
 try{
  const result=await item<CheckoutRetirement>("/v1/customer/checkouts/retire","POST",{request_key:key});
  if(stamp!==version)return;
  const invalidPurchase=result.status==="purchased"&&(!result.intent||result.intent.state!=="purchased"||result.intent.subscription_id==null);
  const invalidRetirement=result.status==="retired"&&result.intent!==null&&(result.intent.subscription_id!=null||!["cancelled","expired"].includes(result.intent.state));
  if(result.request_key!==key||!["retired","purchased"].includes(result.status)||invalidPurchase||invalidRetirement)throw new Error("The cancellation result could not be confirmed. Retry the retained cancellation.");
  if(result.intent)retain(result.intent);
  createAttempt.value=null;createUncertain.value=false;retirementPending.value=false;
  retirementMessage.value=result.status==="purchased"?"The purchase already completed. Its service is preserved.":"This request is cancelled. A delayed response cannot purchase this request. Any approved payment remains in your wallet.";
 }catch(cause){if(stamp===version)fail(cause);}
 finally{if(stamp===version)busy.value=false;}
}
async function perform(action:"cancel"|"reconfirm"):Promise<void>{if(!intent.value)return;const stamp=version;error.value="";if(actionAttempt.value&&actionAttempt.value.action!==action){error.value="Retry the retained operation before starting a different action.";return;}if(!actionAttempt.value){if(action==="reconfirm"&&!offer.value)return;const base={request_key:crypto.randomUUID(),expected_revision:intent.value.revision};actionAttempt.value=action==="reconfirm"?{action,body:{...base,expected_price_rial:offer.value!.price_rial,expected_offer_sha256:offer.value!.offer_sha256}}:{action,body:base};}busy.value=true;try{const row=await item<CheckoutIntent>(`/v1/customer/checkouts/${intent.value.id}/${action}`,"POST",actionAttempt.value.body);if(stamp!==version)return;retain(row);actionAttempt.value=null;actionUncertain.value=false;}catch(cause){if(stamp!==version)return;if(cause instanceof ApiError&&cause.status>=400&&cause.status<500&&!actionUncertain.value)actionAttempt.value=null;else actionUncertain.value=true;fail(cause);}finally{if(stamp===version)busy.value=false;}}
watch(()=>[props.open,props.plan?.id,props.checkoutId] as const,([open,planId,id],old)=>{if(!open)return;if(intent.value?.id===id&&id!==null)return;if(old&&old[0]&&planId===old[1]&&id===old[2])return;version++;destinationVersion++;offer.value=null;intent.value=null;createAttempt.value=null;actionAttempt.value=null;createUncertain.value=actionUncertain.value=retirementPending.value=false;retirementMessage.value="";funding.value="wallet_only";amount.value="";autoRenew.value=false;changeAction.value="require_confirmation";destination.value=null;destinations.value=[];destinationState.value="idle";page.value=pages.value=1;void refresh();},{immediate:true});
watch(funding,mode=>{if(mode==="approved_topup"&&props.preferences?.checkout.destination_mode!=="legacy"&&destinationState.value==="idle")void loadDestinations();});
onUnmounted(()=>{version++;destinationVersion++;});
</script>
<template><Modal :model-value="open" title="Plan checkout" :busy="busy||unresolved||Boolean(actionAttempt)" wide @update:model-value="value=>{if(!value)emit('close');}"><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="retirementMessage" class="hint-box" role="status">{{retirementMessage}}</p><button type="button" class="btn secondary" :disabled="busy||unresolved" @click="refresh">Refresh checkout</button><p v-if="readState==='loading'">Loading checkout…</p><template v-if="intent"><h3>Checkout #{{intent.id}}</h3><p role="status">{{labels[intent.state]}}</p><p>Plan #{{intent.plan_id}} · price {{toman(intent.price_rial)}} · expires {{faDate(intent.expires_at)}}</p><p v-if="reasonMessage" class="hint-box">{{reasonMessage}}</p><p v-if="intent.delivery_mode==='manual_profiles'">Configuration assignment requires operator action. A recorded purchase is not a delivered connection.</p><p v-if="intent.state==='cancelled'||intent.state==='expired'">An approved payment remains in your wallet. This checkout will not purchase a service.</p><p v-if="intent.state==='awaiting_funding'">After payment approval, your selected plan is processed automatically. Ambiguous bank messages remain under review.</p><p v-if="intent.topup_id!==null">The transfer amount below funds your wallet. The saved plan price above is charged separately when this checkout is processed.</p><TopupEvidence v-if="intent.topup_id!==null" :topup-id="intent.topup_id" audience="customer" :pending="intent.state==='awaiting_funding'" :can-upload="preferences?.receipts.enabled??false" /><RouterLink v-if="intent.subscription_id!==null" class="btn" :to="{path:'/account',query:{subscription_id:intent.subscription_id}}" @click="emit('close')">View purchased service</RouterLink><section v-if="intent.state==='action_required'&&offer" class="hint-box"><h3>Review the current offer</h3><p>{{offer.plan_title}} · {{toman(offer.price_rial)}} · {{offer.membership_count}} connection options</p><p>{{offer.quota_bytes===null?'Unlimited data':`${offer.quota_bytes/1024**3} GiB`}} · {{offer.duration_days===null?'No expiry':`${offer.duration_days} days`}}</p><p>{{offer.delivery_mode==='manual_profiles'?'Manual configuration assignment by the operator':'Configured connection bundle'}}</p><button class="btn" :disabled="busy||Boolean(actionAttempt&&actionAttempt.action!=='reconfirm')" @click="perform('reconfirm')">{{actionAttempt?.action==='reconfirm'?'Retry confirmation':'Confirm updated offer'}}</button></section><section v-if="actionAttempt && (intent.state!=='action_required'||actionAttempt.action==='cancel')" class="hint-box" role="status"><p>The previous operation has an unresolved response. Retry its retained request to confirm the outcome.</p><button class="btn" :disabled="busy" @click="perform(actionAttempt.action)">{{actionAttempt.action==='reconfirm'?'Retry retained confirmation':'Retry retained cancellation'}}</button></section><button v-if="!terminal" class="btn secondary" :disabled="busy||Boolean(actionAttempt&&actionAttempt.action!=='cancel')" @click="perform('cancel')">{{actionAttempt?.action==='cancel'?'Retry cancellation':'Cancel checkout'}}</button></template><form v-else-if="offer" class="form-grid" @submit.prevent="create"><h3>{{offer.plan_title}}</h3><PlanIpAllowance :policy="offer.effective_ip_policy"/><p><strong>{{toman(offer.price_rial)}}</strong> · {{offer.quota_bytes===null?'Unlimited data':`${offer.quota_bytes/1024**3} GiB`}} · {{offer.duration_days===null?'No expiry':`${offer.duration_days} days`}}</p><p>{{offer.membership_count}} connection options · {{offer.delivery_mode==='manual_profiles'?'Manual configuration assignment':'Configured bundle'}}</p><p v-if="unresolved" role="status">The previous response was not confirmed. Retry the same request; its details are retained.</p><section v-if="unresolved" class="hint-box"><p v-if="retirementPending">Cancellation has an unresolved response. Retry cancellation before starting another purchase.</p><button type="button" class="btn secondary" :disabled="busy" @click="retire">{{retirementPending?'Retry request cancellation':'Cancel unresolved request'}}</button></section><fieldset class="form-grid" :disabled="busy||unresolved"><label class="field"><span>Purchase funding</span><select v-model="funding"><option value="wallet_only">Existing wallet balance</option><option value="approved_topup">Payment approval then automatic purchase</option></select></label><template v-if="funding==='approved_topup'"><p>{{preferences?.payment_instructions}}</p><NumField v-model="amount" :decimal="true" label="Requested wallet top-up (toman)" /><p>Create the request before transferring. Its saved instructions show the exact payable RIAL amount and any payment identifier.</p><p v-if="preferences">Allowed payment: {{toman(preferences.checkout.minimum_topup_rial)}} to {{toman(preferences.checkout.maximum_topup_rial)}}</p><section v-if="preferences?.checkout.destination_mode!=='legacy'"><h4>Payment destination</h4><p v-if="destination">Selected: {{destination.title}} · {{destination.recipient}}</p><div class="toolbar"><label class="field"><span>Find payment destination</span><input v-model="destinationQuery" @keydown.enter.prevent="page=1;loadDestinations()" /></label><button type="button" class="btn secondary" @click="page=1;loadDestinations()">Search destinations</button></div><p v-if="destinationState==='loading'">Loading destinations…</p><p v-if="destinationState==='error'">Destinations could not be loaded. Retry the search.</p><p v-if="destinationState==='ready'&&!destinations.length">No payment destinations found.</p><button v-for="row in destinations" :key="row.destination_id" type="button" class="btn secondary" :aria-pressed="destination?.destination_id===row.destination_id" @click="destination=row">{{row.title}} · {{row.bank_name}}</button><button v-if="preferences?.checkout.destination_mode==='optional'" type="button" class="btn secondary" @click="destination=null">No destination selected</button><div class="pager"><button type="button" :disabled="page<=1" @click="page--;loadDestinations()">Previous destinations</button><span>{{page}}</span><button type="button" :disabled="page>=pages" @click="page++;loadDestinations()">Next destinations</button></div></section></template><label class="check-row"><input v-model="autoRenew" type="checkbox" />Renew automatically when my wallet has sufficient funds</label><label class="field"><span>If the plan or price changes</span><select v-model="changeAction"><option value="require_confirmation">Ask me to review the updated offer</option><option value="cancel">Cancel and keep my wallet funds</option></select></label></fieldset><button class="btn" :disabled="busy||retirementPending||!offer.default_expiry_seconds">{{unresolved?'Retry same checkout':'Confirm checkout'}}</button></form></Modal></template>
<style scoped>fieldset{border:0;margin:0;padding:0;min-inline-size:0}</style>
